SELECT 'candidate_rows' section,COUNT(*) exact_rows,COUNT(DISTINCT e.master_id) masters,SUM(e.edition='human') human,SUM(e.edition='yanhe') yanhe FROM expected e JOIN song_masters m ON m.id=e.master_id JOIN song_instances i ON i.id=e.instance_id JOIN storage_objects o ON o.id=e.object_id JOIN storage_entries f ON f.id=e.entry_id WHERE m.album_id=e.album_id AND m.title=e.title AND m.duration=e.master_duration AND m.track IS e.master_track AND m.disc IS e.master_disc AND i.master_id=e.instance_master_id AND i.storage_object_id=e.storage_object_id AND i.source_type=e.source_type AND i.storage_uri=e.storage_uri AND i.suffix=e.instance_suffix AND i.content_type=e.instance_content_type AND i.duration=e.instance_duration AND i.size=e.instance_size AND i.missing=e.missing AND i.tag_scanned=e.tag_scanned AND o.physical_key=e.physical_key AND o.suffix=e.object_suffix AND o.content_type=e.object_content_type AND o.size=e.object_size AND f.source_id=e.source_id AND f.path=e.path AND f.display_name=e.display_name AND f.kind=e.kind AND f.object_id=e.entry_object_id AND f.instance_id=e.entry_instance_id;
SELECT 'edition_rows' edition,COUNT(*) tracks,SUM(m.duration) duration,SUM(i.size) size,MIN(m.track) old_track,MAX(m.track) old_track_max FROM song_masters m JOIN song_instances i ON i.master_id=m.id WHERE m.id IN('sm-upload-7b633873-0cf','sm-upload-f9cc4c12-b05','sm-upload-6ae335a4-f5e','sm-upload-9cce0305-cb1','sm-upload-ef4db283-bb5','sm-upload-029009bc-97a','sm-upload-1273fb4a-957','sm-upload-f51aee74-892','sm-upload-ab615a90-cf4','sm-upload-2040526b-b38','sm-upload-ba8d2668-76b','sm-upload-edb17e35-203','sm-upload-3cb1fb29-72a','sm-upload-7c9ebd84-c0a','sm-upload-310b290a-07e','sm-upload-83a779ba-dc3','sm-upload-f227f92c-ec5','sm-upload-596e2550-992','sm-upload-433c6b9a-4a9','sm-upload-cd027b86-380','sm-upload-99ee03c4-341','sm-upload-69ed7ba3-9e5','sm-upload-7e34aa0d-bdd','sm-upload-cbb8756e-98d','sm-upload-2ae5d29e-d99','sm-upload-50f06025-592') GROUP BY CASE WHEN m.id IN ('sm-upload-7b633873-0cf','sm-upload-f9cc4c12-b05','sm-upload-6ae335a4-f5e','sm-upload-9cce0305-cb1','sm-upload-ef4db283-bb5','sm-upload-029009bc-97a','sm-upload-1273fb4a-957','sm-upload-f51aee74-892','sm-upload-ab615a90-cf4','sm-upload-2040526b-b38','sm-upload-ba8d2668-76b','sm-upload-edb17e35-203','sm-upload-3cb1fb29-72a') THEN 'human' ELSE 'yanhe' END;
